1	package loja.checkout.servico;
2	
3	import java.math.BigDecimal;
4	import java.util.ArrayList;
5	import java.util.List;
6	import org.springframework.stereotype.Service;
7	
8	import loja.checkout.dominio.Cupom;
9	import loja.checkout.dominio.Dinheiro;
10	import loja.checkout.dominio.Entrega;
11	import loja.checkout.dominio.ErroCheckout;
12	import loja.checkout.dominio.FormaPagamento;
13	import loja.checkout.dominio.Item;
14	import loja.checkout.dominio.NivelClube;
15	import loja.checkout.dominio.Pagamento;
16	import loja.checkout.dominio.Regiao;
17	import loja.checkout.web.ItemRequisicao;
18	import loja.checkout.web.RequisicaoResumo;
19	import loja.checkout.web.RespostaResumo;
20	
21	@Service
22	public class CheckoutServico {
23	
24	    public RespostaResumo calcular(RequisicaoResumo req) {
25	        List<Item> itens = itensValidos(req.itens());
26	        NivelClube nivel = parse(NivelClube.class, req.nivelClube(), "NIVEL_CLUBE_INVALIDO");
27	        Regiao regiao = parse(Regiao.class, req.regiao(), "REGIAO_INVALIDA");
28	        Entrega entrega = parse(Entrega.class, req.modalidadeEntrega(), "MODALIDADE_INVALIDA");
29	
30	        BigDecimal peso = peso(itens);
31	        if (!entrega.atende(peso)) {
32	            throw new ErroCheckout("MODALIDADE_INDISPONIVEL");
33	        }
34	
35	        BigDecimal subtotal = subtotal(itens);
36	        BigDecimal freteBase = entrega.valorFrete(peso);
37	        BigDecimal frete = nivel.freteGratis() ? Dinheiro.centavos(BigDecimal.ZERO) : freteBase;
38	
39	        Cupom cupom = null;
40	        BigDecimal descontoCupom = Dinheiro.centavos(BigDecimal.ZERO);
41	        if (req.cupom() != null && !req.cupom().isBlank()) {
42	            cupom = parse(Cupom.class, req.cupom(), "CUPOM_INVALIDO");
43	            if (!cupom.aplicavel(subtotal)) {
44	                throw new ErroCheckout("CUPOM_NAO_APLICAVEL");
45	            }
46	            descontoCupom = cupom.desconto(subtotal, frete, itens);
47	        }
48	
49	        FormaPagamento forma = parse(FormaPagamento.class, req.formaPagamento(), "FORMA_PAGAMENTO_INVALIDA");
50	        int parcelas = req.parcelas() == null ? 1 : req.parcelas();
51	        if (!forma.parcelasValidas(parcelas)) {
52	            throw new ErroCheckout("PARCELAMENTO_INVALIDO");
53	        }
54	
55	        BigDecimal seguro = regiao.seguro(subtotal);
56	        BigDecimal totalPedido = Dinheiro.centavos(
57	                subtotal.subtract(descontoCupom).add(frete).add(seguro));
58	
59	        if (!forma.atende(totalPedido)) {
60	            throw new ErroCheckout("FORMA_PAGAMENTO_INDISPONIVEL");
61	        }
62	
63	        Pagamento pagamento = forma.calcular(totalPedido, parcelas);
64	        BigDecimal totalFinal = Dinheiro.centavos(totalPedido.add(pagamento.ajuste()));
65	
66	        return new RespostaResumo(
67	                subtotal,
68	                descontoCupom,
69	                frete,
70	                entrega.prazoDias(),
71	                seguro,
72	                pagamento.ajuste(),
73	                totalFinal,
74	                parcelas,
75	                pagamento.valorParcela(),
76	                nivel.credito(subtotal),
77	                nivel.brinde(subtotal));
78	    }
79	
80	    private static List<Item> itensValidos(List<ItemRequisicao> entrada) {
81	        if (entrada == null || entrada.isEmpty()) {
82	            throw new ErroCheckout("PEDIDO_INVALIDO");
83	        }
84	        List<Item> itens = new ArrayList<>(entrada.size());
85	        for (ItemRequisicao i : entrada) {
86	            if (i == null
87	                    || i.precoUnitario() == null || i.precoUnitario().signum() <= 0
88	                    || i.quantidade() == null || i.quantidade() <= 0
89	                    || i.pesoKg() == null || i.pesoKg().signum() <= 0) {
90	                throw new ErroCheckout("PEDIDO_INVALIDO");
91	            }
92	            itens.add(new Item(i.nome(), i.precoUnitario(), i.quantidade(), i.pesoKg()));
93	        }
94	        return itens;
95	    }
96	
97	    private static BigDecimal subtotal(List<Item> itens) {
98	        BigDecimal soma = BigDecimal.ZERO;
99	        for (Item i : itens) {
100	            soma = soma.add(i.precoUnitario().multiply(BigDecimal.valueOf(i.quantidade())));
101	        }
102	        return Dinheiro.centavos(soma);
103	    }
104	
105	    private static BigDecimal peso(List<Item> itens) {
106	        BigDecimal soma = BigDecimal.ZERO;
107	        for (Item i : itens) {
108	            soma = soma.add(i.pesoKg().multiply(BigDecimal.valueOf(i.quantidade())));
109	        }
110	        return soma;
111	    }
112	
113	    private static <E extends Enum<E>> E parse(Class<E> tipo, String valor, String codigoErro) {
114	        if (valor == null) {
115	            throw new ErroCheckout(codigoErro);
116	        }
117	        try {
118	            return Enum.valueOf(tipo, valor);
119	        } catch (IllegalArgumentException e) {
120	            throw new ErroCheckout(codigoErro);
121	        }
122	    }
123	}
