3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	
6	import static loja.checkout.dominio.Dinheiro.centavos;
7	
8	public enum FormaPagamento {
9	    PIX {
10	        public Pagamento calcular(BigDecimal totalPedido, int parcelas) {
11	            BigDecimal desconto = centavos(totalPedido.multiply(new BigDecimal("0.05")));
12	            BigDecimal ajuste = desconto.negate();
13	            BigDecimal valorParcela = centavos(totalPedido.add(ajuste));
14	            return new Pagamento(ajuste, valorParcela);
15	        }
16	        public boolean parcelasValidas(int parcelas) { return parcelas == 1; }
17	        public boolean atende(BigDecimal totalPedido) { return true; }
18	    },
19	    BOLETO {
20	        public Pagamento calcular(BigDecimal totalPedido, int parcelas) {
21	            BigDecimal ajuste = new BigDecimal("3.49");
22	            BigDecimal valorParcela = centavos(totalPedido.add(ajuste));
23	            return new Pagamento(ajuste, valorParcela);
24	        }
25	        public boolean parcelasValidas(int parcelas) { return parcelas == 1; }
26	        public boolean atende(BigDecimal totalPedido) {
27	            return totalPedido.compareTo(new BigDecimal("1000.00")) <= 0;
28	        }
29	    },
30	    CARTAO {
31	        private static final BigDecimal TAXA = new BigDecimal("0.0199");
32	
33	        public Pagamento calcular(BigDecimal totalPedido, int parcelas) {
34	            if (parcelas <= 3) {
35	                BigDecimal valorParcela = totalPedido.divide(BigDecimal.valueOf(parcelas), 2, RoundingMode.HALF_EVEN);
36	                return new Pagamento(centavos(BigDecimal.ZERO), valorParcela);
37	            }
38	            BigDecimal umMaisI = BigDecimal.ONE.add(TAXA);
39	            BigDecimal umMaisIaN = umMaisI.pow(parcelas);
40	            BigDecimal numerador = totalPedido.multiply(TAXA).multiply(umMaisIaN);
41	            BigDecimal denominador = umMaisIaN.subtract(BigDecimal.ONE);
42	            BigDecimal parcela = centavos(numerador.divide(denominador, 10, RoundingMode.HALF_EVEN));
43	            BigDecimal totalFinal = parcela.multiply(BigDecimal.valueOf(parcelas));
44	            BigDecimal ajuste = centavos(totalFinal.subtract(totalPedido));
45	            return new Pagamento(ajuste, parcela);
46	        }
47	        public boolean parcelasValidas(int parcelas) { return parcelas >= 1 && parcelas <= 12; }
48	        public boolean atende(BigDecimal totalPedido) { return true; }
49	    };
50	
51	    public abstract Pagamento calcular(BigDecimal totalPedido, int parcelas);
52	    public abstract boolean parcelasValidas(int parcelas);
53	    public abstract boolean atende(BigDecimal totalPedido);
54	}
